rows=[('OS','Linux / Windows'),('Host','Bangalore'),('Role','Software Engineer Intern'),('Company','TechnoTribes'),('Focus','Backend & Full-Stack Engineering'),('Languages','Python · JavaScript · TypeScript · SQL'),('Backend','Node.js · Express · Django · FastAPI'),('Frontend','React · Next.js · HTML · CSS'),('Data','MySQL · Redis'),('Tools','Git · GitHub · Docker · Linux · VS Code'),('GitHub','AADIKASHYAP'),('LinkedIn','adarshkashyap14'),('Email','adarshkashyap14@gmail.com')]
body=''.join(f'<g class="line" style="animation-delay:{i*.06:.2f}s"><text x="42" y="{90+i*33}" class="key">{escape(k)}</text><text x="210" y="{90+i*33}" class="value">{escape(v)}</text></g>' for i,(k,v) in enumerate(rows))
svg='''<svg xmlns="http://www.w3.org/2000/svg" width="900" height="560"><defs><style>.card{fill:#0d0d0d;stroke:#D4AF37;stroke-opacity:.42}.bar{fill:#171717}.key{fill:#D4AF37;font:600 17px monospace}.value{fill:#d8d8d8;font:16px monospace}.line{opacity:0;animation:fade .5s ease forwards}@keyframes fade{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:translateX(0)}}</style></defs><rect class="card" x="1" y="1" width="898" height="558" rx="22"/><rect class="bar" x="1" y="1" width="898" height="55" rx="22"/><circle cx="28" cy="28" r="7" fill="#ff5f57"/><circle cx="52" cy="28" r="7" fill="#febc2e"/><circle cx="76" cy="28" r="7" fill="#28c840"/><text x="105" y="34" fill="#f1f1f1" font="600 17px monospace">The Cipher Stack</text><line x1="28" y1="70" x2="872" y2="70" stroke="#D4AF37" stroke-opacity=".18"/>%s</svg>'''%body
